import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.DrDMl0tG.js";const b=JSON.parse('{"title":"Server Example: Heavy Objects on Cloth","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/heavy_objects_on_cloth.md","filePath":"sections/examples/server/heavy_objects_on_cloth.md"}'),r={name:"sections/examples/server/heavy_objects_on_cloth.md"};function h(l,e,n,d,i,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-heavy-objects-on-cloth" tabindex="-1">Server Example: Heavy Objects on Cloth <a class="header-anchor" href="#server-example-heavy-objects-on-cloth" aria-label="Permalink to &quot;Server Example: Heavy Objects on Cloth&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Three loads rest on cloth: a 10 kg ball on a cloth on the ground, a 5 kg box on two stacked cloths, and a 5 kg blanket draped over a 1 kg box. The cloth is solved together with the bodies (<a href="./../../DeformableObject.html#solving-deformables-together-with-the-bodies"><code>World::setMonolithicDeformables()</code></a>), so each load rests on what carries the cloth: the ball and the box on the ground through the cloth, and the blanket on the box, which carries the blanket&#39;s weight to the ground. Every five seconds the world starts over, and the example prints how far each load pressed into what carries it.</p><table tabindex="0"><thead><tr><th>Load</th><th>Default coupling</th><th>Solved together</th></tr></thead><tbody><tr><td>Cloth under the 10 kg ball, pressed into the ground</td><td>10.8 mm</td><td>&lt; 0.001 mm</td></tr><tr><td>Upper cloth under the 5 kg box, pressed into the lower one</td><td>18 mm</td><td>0.4 mm</td></tr><tr><td>1 kg box under the 5 kg blanket, pressed into the ground</td><td>30 mm</td><td>0.03 mm</td></tr></tbody></table><p>Solved together, the scene also steps faster (3.3 ms instead of 4.8 ms per 1 ms step on a Ryzen 9 3950X), since the contacts under the loads settle in fewer iterations.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>heavy_objects_on_cloth</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable and connect <code>rayrai_tcp_viewer</code> to port 8080:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/heavy_objects_on_cloth</span></span></code></pre></div><p>On Windows, run <code>build-examples/bin/heavy_objects_on_cloth.exe</code> instead.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The cloths are particle meshes with nearly inextensible edges and a bending modulus of 1e-4 N m; their particles collide as 8 mm spheres. The cloth under the ball is 0.64 m square and weighs 0.2 kg; the stacked cloths are 0.32 m square and weigh 0.1 kg each, the blanket is 0.5 m square.</li><li>The ball and the box are dropped from a few centimetres; the blanket falls 20 cm onto the box and drapes over its edges to the ground.</li><li>The scene lives in <code>include/heavy_objects_on_cloth.hpp</code>, so the same scene can run without a viewer (<code>Scene::Step()</code>), as the RaiSim test of the example does.</li></ul>',13)])])}const m=t(r,[["render",h]]);export{b as __pageData,m as default};
